import{_ as t,o as a,c as r,ak as n}from"./chunks/framework.B8jO0odJ.js";const g=JSON.parse(`{"title":"AI lessons paired with the existing A–Z source terms","description":"Draft prepared October 28, 2026 for Sherwin's design review and Sean's authored lesson copy. The Web3 Young Learners Encyclopedia source contents keep their original 26 A–Z te","frontmatter":{"title":"AI lessons paired with the existing A–Z source terms","description":"Draft prepared October 28, 2026 for Sherwin's design review and Sean's authored lesson copy. The Web3 Young Learners Encyclopedia source contents keep their original 26 A–Z te","source":"docs/archive/pre-lesson-collection-2026-11-11/planning/a-z-ai-paired-lessons-draft.md","category":"Archive","sourceUpdated":"2026-11-11T12:24:37+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/archive/pre-lesson-collection-2026-11-11/planning/a-z-ai-paired-lessons-draft.md","filePath":"content/docs/archive/pre-lesson-collection-2026-11-11/planning/a-z-ai-paired-lessons-draft.md"}`),s={name:"content/docs/archive/pre-lesson-collection-2026-11-11/planning/a-z-ai-paired-lessons-draft.md"};function i(o,e,d,c,l,h){return a(),r("div",null,[...e[0]||(e[0]=[n('<div><h1 id="ai-lessons-paired-with-the-existing-az-source-terms">AI lessons paired with the existing A–Z source terms<a class="header-anchor" href="#ai-lessons-paired-with-the-existing-az-source-terms" aria-label="Link to this section">​</a></h1><p>Draft prepared October 28, 2026 for Sherwin&#39;s design review and Sean&#39;s authored lesson copy. The <a href="/Chainy-Docs/content/docs/archive/source-material/web3-young-learners-encyclopedia-a-z-contents.html"><em>Web3 Young Learners Encyclopedia</em> source contents</a> keep their original 26 A–Z terms and page references unchanged. The existing <a href="/Chainy-Docs/content/docs/planning/a-z-lesson-grouping-draft.html">Web3/Blockchain grouping</a> gives those terms 26 lesson slots. <strong>Thirteen of those slots also carry a distinct AI lesson with the same letter.</strong> This is one A–Z structure with 13 AI pairings; it does not replace a source term or claim that the encyclopedia covers AI.</p><p>The AI vocabulary comes from the <a href="https://developers.google.com/machine-learning/glossary/">Google Machine Learning Glossary</a>, <a href="https://developers.google.com/machine-learning/crash-course">Google Machine Learning Crash Course</a>, <a href="https://www.unesco.org/en/articles/ai-competency-framework-students">UNESCO&#39;s AI Competency Framework for Students</a>, and other primary sources cited per row. These are source references for accurate lesson writing, not a claim of school curriculum approval. The <a href="/Chainy-Docs/content/docs/planning/ai-source-research.html">source research note</a> records the source rationale and cautions. Pairing means the original term supplies a familiar game situation; it does <strong>not</strong> mean the two terms have the same definition.</p><p>The formats below are proposals: <strong>four very short mini-game lessons and nine contextual quizzes</strong>. A mini-game is a bounded card or choice interaction using fictional data and existing UI patterns. The lessons are full-curriculum planning, subject to Sherwin&#39;s content decision and Sean&#39;s copy. The current A01–A03 classifier stays conditional on the core Android checks; A04–A05 remain later scope.</p><table><thead><tr><th>Letter</th><th>Original source term (PDF page)</th><th>Paired AI term and learner check</th><th>Format</th><th>AI source</th></tr></thead><tbody><tr><td>A</td><td>Altcoins (8)</td><td><strong>Artificial intelligence:</strong> identify when a helper is making a prediction rather than following a fixed purchase rule.</td><td>Quiz</td><td><a href="https://oecd.ai/en/wonk/definition">OECD AI system definition</a></td></tr><tr><td>B</td><td>Blockchain (9)</td><td><strong>Bias:</strong> find a missing or overrepresented kind of training example; a correct ledger does not make advice fair.</td><td>Quiz</td><td><a href="https://developers.google.com/machine-learning/crash-course/fairness/types-of-bias">Google, types of bias</a></td></tr><tr><td>C</td><td>Cryptocurrency (10)</td><td><strong>Classification:</strong> explain why the helper sorts fictional transaction requests into Routine or Review.</td><td>Quiz after classifier use</td><td><a href="https://developers.google.com/machine-learning/intro-to-ml/what-is-ml">Google, ML introduction</a></td></tr><tr><td>D</td><td>Decentralization (11)</td><td><strong>Dataset:</strong> distinguish many copies of one record from varied examples that help teach a model.</td><td>Quiz</td><td><a href="https://developers.google.com/machine-learning/crash-course/overfitting/data-characteristics">Google, data characteristics</a></td></tr><tr><td>F</td><td>Fiat Currency (13)</td><td><strong>Feature:</strong> choose relevant details from a fictional request; payment type alone cannot decide whether review is needed.</td><td>Mini-game: select useful fields</td><td><a href="https://developers.google.com/machine-learning/intro-to-ml/supervised">Google, supervised learning</a></td></tr><tr><td>G</td><td>Gas Fees (14)</td><td><strong>Generative AI:</strong> recognize generated explanatory content and check a fee explanation against the displayed transaction.</td><td>Quiz with an authored example</td><td><a href="https://developers.google.com/machine-learning/glossary/generative">Google, generative AI glossary</a></td></tr><tr><td>H</td><td>HODL (15)</td><td><strong>Human oversight:</strong> keep a consequential decision with the player after checking evidence; do not follow speculative advice blindly.</td><td>Mini-game: inspect and approve/reject; later A05</td><td><a href="https://www.unesco.org/en/articles/ai-competency-framework-students">UNESCO, human agency and accountability</a></td></tr><tr><td>L</td><td>Ledger (19)</td><td><strong>Label:</strong> attach Routine or Review to fictional request examples using visible ledger evidence, then inspect a disagreement.</td><td>Mini-game: label request cards</td><td><a href="https://developers.google.com/machine-learning/intro-to-ml/supervised">Google, supervised learning</a></td></tr><tr><td>M</td><td>Mining &amp; Validators (20)</td><td><strong>Model:</strong> distinguish a learned prediction model from a blockchain network&#39;s stated validation rules.</td><td>Quiz</td><td><a href="https://developers.google.com/machine-learning/glossary/fundamentals">Google, ML fundamentals glossary</a></td></tr><tr><td>P</td><td>Proof Systems (23)</td><td><strong>Prediction:</strong> explain why an AI suggestion can be wrong and does not prove a transaction valid.</td><td>Quiz</td><td><a href="https://developers.google.com/machine-learning/glossary/fundamentals">Google, ML fundamentals glossary</a></td></tr><tr><td>R</td><td>Risks, Red Flags &amp; Staying Scam-Safe (25)</td><td><strong>Responsible AI:</strong> check privacy, possible harm, and limits before using AI advice.</td><td>Quiz</td><td><a href="https://www.unesco.org/en/articles/ai-competency-framework-students">UNESCO student framework</a>; <a href="https://airc.nist.gov/airmf-resources/airmf/3-sec-characteristics/">NIST trustworthiness characteristics</a></td></tr><tr><td>T</td><td>Tokens (27)</td><td><strong>Training:</strong> explain that a model fits from labeled examples of fictional requests; blockchain asset tokens are a separate idea.</td><td>Quiz after training action</td><td><a href="https://developers.google.com/machine-learning/intro-to-ml/supervised">Google, supervised learning</a></td></tr><tr><td>V</td><td>Volatility (29)</td><td><strong>Validation:</strong> test a trained model on unseen cases, inspect mistakes, and reserve untouched cases for the final check.</td><td>Mini-game: fresh-case test</td><td><a href="https://developers.google.com/machine-learning/crash-course/overfitting/dividing-datasets">Google, dividing datasets</a></td></tr></tbody></table><h2 id="four-short-mini-game-candidates">Four short mini-game candidates<a class="header-anchor" href="#four-short-mini-game-candidates" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Letter</th><th>Player action and feedback</th><th>Evidence of reasoning</th><th>Delivery fit</th></tr></thead><tbody><tr><td>F</td><td>Select two useful fields on a synthetic request card, then see why an irrelevant field would mislead the helper.</td><td>Explains a chosen feature rather than merely tapping it.</td><td>Reuse the A01 card UI; freeze actual classifier features with Christian before implementation.</td></tr><tr><td>L</td><td>Label a few synthetic requests Routine or Review, fit the local classifier, and inspect one changed prediction after a corrected label.</td><td>Connects an example label to the helper&#39;s output.</td><td>Fits A01–A02 only if predictions really depend on the labeled examples.</td></tr><tr><td>V</td><td>Predict how the helper will classify two previously unseen cards; run it, inspect one mistake, then answer a new case.</td><td>Distinguishes training examples from fresh evaluation.</td><td>Fits A02–A03. Do not recycle the final reserved cases during practice.</td></tr><tr><td>H</td><td>Compare a proposed dispatch or recommendation with the ledger, then approve or reject with a reason.</td><td>Cites the record or a missing fact before allowing action.</td><td>Fits later A04–A05. A scripted helper response must be labeled as a simulation.</td></tr></tbody></table><p>The F/L/V interactions can share a single card presentation and classifier flow; H can reuse the later evidence/choice panel. None calls for a cloud model, real account, real transaction, or personal learner records. A handful of correct cards shows performance in this toy activity, not real-world reliability. A quiz should ask for a reason or a changed example, not just a memorized definition.</p><h2 id="delivery-and-review-boundary">Delivery and review boundary<a class="header-anchor" href="#delivery-and-review-boundary" aria-label="Link to this section">​</a></h2><p>The adopted November 10 beta remains W01–W04 and B01–B03/demo B07 with dependable local saves. The A01–A03 classifier is stretch work only after core Android checks and a capacity decision. The November 21 pre-final still needs integration, QA, manuscript evidence, and rehearsal. Adding 13 AI pairings to the full curriculum creates substantial copy, review, UI, and test work; it is not a justified November 10 commitment without measured capacity. Sherwin should approve the pairings and learning outcomes; Sean authors final lessons; Christian verifies whether the classifier is genuinely example-trained; Miguel and Luis handle their respective UI and art handoffs through the team board.</p></div>',1)])])}const u=t(s,[["render",i]]);export{g as __pageData,u as default};
